        onlineActiveCount++;
        const cpu = rec.cpu?.usage || 0;
        totalCpu += cpu;
        if (cpu > maxCpu) {
          maxCpu = cpu;
          maxCpuNode = node.name || node.uuid.slice(0, 6);
        }

        usedRam += rec.ram?.used || 0;
        usedSwap += rec.swap?.used || 0;

