const formatSpeed = (bytes: number): string => {
  if (bytes === 0) return "0 B/s";
  const units = ["B/s", "KB/s", "MB/s", "GB/s", "TB/s"];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  const size = bytes / Math.pow(1024, i);
  let decimals = 2;
  if (i >= 3) decimals = 1;
  if (i <= 1) decimals = 0;
  if (size >= 100) decimals = 0;
  return `${size.toFixed(decimals)} ${units[i]}`;
};

export default function DashboardContent() {
  const { t } = useTranslation();
  const { nodeList } = useNodeList();
  const { live_data } = useLiveData();
  const { publicInfo } = usePublicInfo();
  const { themeConfig } = useTheme();
  const isMounted = useMounted();
  const statusCardsVisibility = useStatusCardsVisibility();

  if (!isMounted) {
    return <Loading />;
  }

  const nodes = nodeList ?? [];
  const live = live_data?.data ?? { online: [], data: {} };
  const onlineCount = nodes.filter((node) => live.online?.includes(node.uuid)).length;

  let totalDown = 0;
  let totalUp = 0;
  let totalTransfer = 0;

  nodes.forEach((node) => {
    const rec = live.data?.[node.uuid];
    if (rec?.network) {
      totalDown += rec.network.down || 0;
      totalUp += rec.network.up || 0;
      totalTransfer += (rec.network.totalUp || 0) + (rec.network.totalDown || 0);
    }
  });

  return (
    <div className="container mx-auto px-4 space-y-6">
      <Callouts />

      {/* Aurora Cluster Board (Top Fleet HUD) */}
      <AuroraClusterBoard
        nodes={nodes}
        liveData={live}
      />

      {/* Server Node Cards Grid / Table */}
      <Suspense fallback={<div className="p-4">{t("nodes.loading", { defaultValue: "Loading nodes..." })}</div>}>
        <NodeDisplay
          nodes={nodes}
          liveData={live}
        />
      </Suspense>
    </div>
  );
}
